import{_ as d,o as r,c as e,a6 as a}from"./chunks/framework.B_q3ZJNF.js";const u=JSON.parse('{"title":"术语表","description":"","frontmatter":{"title":"术语表"},"headers":[],"relativePath":"astock-course/glossary.md","filePath":"astock-course/docs/glossary.md"}'),s={name:"astock-course/glossary.md"};function i(o,t,n,c,l,m){return r(),e("div",null,[...t[0]||(t[0]=[a('<h1 id="术语表" tabindex="-1">术语表 <a class="header-anchor" href="#术语表" aria-label="Permalink to &quot;术语表&quot;">​</a></h1><p>全书 71 个术语，按首教顺序排列；「定义」是它是什么，「接口」是怎么用（接口收在各章正文与「工具箱」槽）。回查正文可用站内搜索。</p><table tabindex="0"><thead><tr><th>术语</th><th>英文</th><th>它是什么</th></tr></thead><tbody><tr><td>货币时间价值</td><td>time value of money</td><td>今天的一笔钱比未来的同额更值钱，因为它能立刻投入增值，等待本身有代价。</td></tr><tr><td>复利</td><td>compound interest</td><td>每期收益并入本金一起再生收益，增长按指数曲线进行而非直线。</td></tr><tr><td>通货膨胀</td><td>inflation</td><td>整体物价水平持续上涨，同样的金额能买到的东西逐年变少。</td></tr><tr><td>实际购买力</td><td>real purchasing power</td><td>名义金额经物价折算后真正能买到的商品与服务数量。</td></tr><tr><td>收益率</td><td>return</td><td>期末相对期初增长的百分比，衡量一笔钱的增值速度。</td></tr><tr><td>股票</td><td>stock</td><td>公司所有权的一份凭证，持有一股就按比例拥有公司的一份。</td></tr><tr><td>股权</td><td>equity</td><td>对公司资产与利润的剩余索取权，公司还清一切欠账后剩下的都归股东。</td></tr><tr><td>市值</td><td>market capitalization</td><td>股价乘以总股本，是市场给公司全部股权开出的总标价。</td></tr><tr><td>盈利</td><td>earnings</td><td>公司一段时期赚到的净利润，长期股价最重要的锚。</td></tr><tr><td>估值</td><td>valuation</td><td>市场价格相对基本面（盈利、净资产）的倍数关系，即市场情绪给基本面的放大倍数。</td></tr><tr><td>集合竞价</td><td>call auction</td><td>把一段时间内的买卖申报集中起来，按最大成交量原则一次性撮合出唯一成交价。</td></tr><tr><td>T+1</td><td>T+1</td><td>当日买入的股票，次一交易日才能卖出（现行载体为沪深交易所《交易规则》；1998 年版《证券法》第 106 条为其历史源头，2005 年修订后删除）——当日卖出所得资金当日可用、次日可取。</td></tr><tr><td>涨跌停板</td><td>price limit</td><td>以前收盘价为基准，限制当日报价的最大波动幅度，触及后价格当天不再超越该价位。</td></tr><tr><td>印花税</td><td>securities stamp tax</td><td>卖出股票时按成交金额的万分之5向卖方单边征收的税（2023-08-28 起，财政部 税务总局公告2023年第39号）。</td></tr><tr><td>佣金</td><td>commission</td><td>券商按成交金额收取的经纪服务费，买卖双向，费率可在开户时协商。</td></tr><tr><td>过户费</td><td>transfer fee</td><td>中国结算按成交金额的万分之0.1双向收取的股权登记过户费（2022-04-29 起）。</td></tr><tr><td>手</td><td>lot</td><td>A股主板与创业板的最小交易单位，1手 = 100股。</td></tr><tr><td>交易日</td><td>trading day</td><td>交易所开市的日子，非节假日周一至周五；T 日、T+1 的「日」都指它。</td></tr><tr><td>K线</td><td>candlestick</td><td>用矩形实体加上下影线，把一个周期的开盘价、收盘价、最高价、最低价画成一根蜡烛。</td></tr><tr><td>阳线与阴线</td><td>bullish / bearish candle</td><td>收盘价高于开盘价收阳线（A股红色），低于则收阴线（A股绿色）。</td></tr><tr><td>上影线与下影线</td><td>upper / lower shadow</td><td>实体上方/下方的细线，记录价格一度到达却没能守住的高点/低点。</td></tr><tr><td>成交量</td><td>volume</td><td>一个周期内成交的股数或金额，是价格运动的燃料。</td></tr><tr><td>均线</td><td>moving average</td><td>最近N个收盘价的算术平均连成的曲线，近似这段时间的平均持仓成本。</td></tr><tr><td>趋势</td><td>trend</td><td>价格运动的方向性：高点低点同时抬升为上升趋势，同时下移为下降趋势，交织为震荡。</td></tr><tr><td>支撑与压力</td><td>support / resistance</td><td>价格容易止跌的区域（支撑）与容易受阻的区域（压力），源于前期密集成交与套牢筹码。</td></tr><tr><td>金叉与死叉</td><td>golden cross / death cross</td><td>短期均线上穿长期均线为金叉，下穿为死叉，是趋势转换的滞后确认。</td></tr><tr><td>资产负债表</td><td>balance sheet</td><td>某一时点公司「有什么、欠什么、股东剩什么」的快照：资产 = 负债 + 所有者权益。</td></tr><tr><td>利润表</td><td>income statement</td><td>一段时期「赚没赚钱」的过程记录：收入减成本费用等于利润。</td></tr><tr><td>现金流量表</td><td>cash flow statement</td><td>一段时期真金白银流入流出的记录，分经营、投资、筹资三类。</td></tr><tr><td>营业收入</td><td>revenue</td><td>公司卖货或提供服务收进来的钱，未扣任何成本。</td></tr><tr><td>毛利率</td><td>gross margin</td><td>毛利除以营收，即卖价里超出直接成本的部分占比。</td></tr><tr><td>净利润</td><td>net profit</td><td>扣完一切成本、费用和税后剩下的利润，市盈率的分母。</td></tr><tr><td>应收账款</td><td>accounts receivable</td><td>货已发出、钱还没收到的部分，是记在账上的纸面收入。</td></tr><tr><td>货币资金</td><td>cash and equivalents</td><td>公司账上随时可动用的钱。</td></tr><tr><td>经营现金流</td><td>operating cash flow</td><td>主营业务实际收进减付出的净现金，是利润的「现金版」。</td></tr><tr><td>市盈率</td><td>P/E ratio</td><td>股价除以每股盈利（或市值除以净利润），按当前盈利水平多少年回本的倍数。</td></tr><tr><td>盈利收益率</td><td>earnings yield</td><td>市盈率的倒数：每一元股价每年赚回多少利润。</td></tr><tr><td>市净率</td><td>P/B ratio</td><td>股价除以每股净资产，价格相对账面家底的倍数。</td></tr><tr><td>股息</td><td>dividend</td><td>公司把一部分利润以现金形式分给股东。</td></tr><tr><td>股息率</td><td>dividend yield</td><td>每年每股分红除以股价，持有股票的年度现金回报率。</td></tr><tr><td>无风险利率</td><td>risk-free rate</td><td>不承担信用风险就能拿到的利率，课程用一年期定期存款挂牌利率作近似锚（2025-05-20 工农中建交五大行 0.95%、邮储 0.98%）。</td></tr><tr><td>内在价值</td><td>intrinsic value</td><td>公司未来能创造的全部现金折算到今天的合计，只能估算区间、不能精算到分。</td></tr><tr><td>安全边际</td><td>margin of safety</td><td>买入价低于估算内在价值的余量，为判断出错预留的缓冲垫。</td></tr><tr><td>能力圈</td><td>circle of competence</td><td>你真正能理解其生意与风险的公司边界，圈内决策、圈外认怂。</td></tr><tr><td>护城河</td><td>moat</td><td>让对手难以复制的结构性优势：品牌、网络效应、成本优势、牌照、转换成本。</td></tr><tr><td>波动率</td><td>volatility</td><td>价格围绕均值上下颠簸的剧烈程度，常用收益率标准差度量。</td></tr><tr><td>最大回撤</td><td>max drawdown</td><td>从历史最高点到其后最低点的最大跌幅，衡量最惨时刻。</td></tr><tr><td>盈亏不对称</td><td>loss-gain asymmetry</td><td>亏损与回本所需涨幅在百分比上不对称：亏50%需要涨100%才回本。</td></tr><tr><td>回本涨幅</td><td>recovery gain</td><td>从当前亏损状态回到成本价所需的上涨百分比。</td></tr><tr><td>分散化</td><td>diversification</td><td>把资金分布在低相关资产上，让任何单一灾难都不至于致命。</td></tr><tr><td>相关性</td><td>correlation</td><td>两个资产涨跌同步程度的度量，取值 −1 到 +1，越接近0互相抵消越强。</td></tr><tr><td>资产配置</td><td>asset allocation</td><td>决定各大类资产（股、债、现金等）比例的顶层设计。</td></tr><tr><td>再平衡</td><td>rebalancing</td><td>组合比例偏离目标后，卖出超配部分、买入低配部分，回到目标配置。</td></tr><tr><td>仓位</td><td>position size</td><td>已投入风险资产的资金占总资金的比例。</td></tr><tr><td>仓位管理</td><td>position management</td><td>按风险预算决定每笔投资金额的规则体系。</td></tr><tr><td>定投</td><td>dollar-cost averaging</td><td>固定时间间隔投入固定金额，用纪律摊平买入成本。</td></tr><tr><td>单笔风险预算</td><td>per-trade risk budget</td><td>愿意为单笔投资承受的最大亏损占总资金的比例，常见1%–2%。</td></tr><tr><td>损失厌恶</td><td>loss aversion</td><td>同额亏损带来的痛苦约为盈利快乐的两倍，导致该卖不卖、该买不买。</td></tr><tr><td>处置效应</td><td>disposition effect</td><td>盈利急着卖、亏损不肯卖的倾向，俗称卖盈持亏。</td></tr><tr><td>锚定效应</td><td>anchoring</td><td>把与价值无关的数字（自己的成本价、历史最高价）当成决策参照点。</td></tr><tr><td>从众效应</td><td>herding</td><td>跟随大多数人行动，结果往往在顶部接盘、底部割肉。</td></tr><tr><td>指数</td><td>index</td><td>按公开规则选出一篮子证券并加权计算的表现标尺。</td></tr><tr><td>宽基指数</td><td>broad-based index</td><td>覆盖全市场多行业的指数（如沪深300、中证500），不押注单一行业。</td></tr><tr><td>指数基金</td><td>index fund</td><td>以复制某指数表现为目标的基金，低费率、持仓透明。</td></tr><tr><td>ETF</td><td>exchange-traded fund</td><td>在交易所像股票一样按市价买卖的指数基金。</td></tr><tr><td>费率</td><td>expense ratio</td><td>基金每年从资产中扣除的管理与运作成本比例。</td></tr><tr><td>商业模式</td><td>business model</td><td>公司赚钱的方式：卖给谁、收什么钱、成本结构如何。</td></tr><tr><td>研究清单</td><td>research checklist</td><td>把分析流程固化为带出口的检查序列，防漏项、防情绪化。</td></tr><tr><td>投资体系</td><td>investment system</td><td>目标、配置、买卖规则、风控红线、复盘节奏的总和。</td></tr><tr><td>投资计划书</td><td>investment policy statement</td><td>把个人投资体系写成的一页纸契约。</td></tr><tr><td>熊市</td><td>bear market</td><td>市场整体长期下跌的阶段。</td></tr></tbody></table>',3)])])}const h=d(s,[["render",i]]);export{u as __pageData,h as default};
